@startuml

class Bettor {
  + name : string
}

class Race {
  + number_of_runners : int
}

class Runner {
  + name : string
}

class Jockey {
  + name : string
}

class Bet {
  + amount : double
  + odds : double
}

Bettor "1" -- "*" Bet : places
Race "1" -- "1..*" Runner : has
Race "1" -- "1" Runner : winner
Runner "1" -- "1" Jockey : is ridden by
Bet "*" -- "1" Race : refers to
Bet "*" -- "1" Runner : refers to

@enduml

